// Gate test G15: the colour tokens equal the specification, Part F2, and keep their contrast.
// Do not edit this file.
import { expect, test } from 'vitest';
import { tokens } from '../../module/core/tokens';

const SPEC: Record<'light' | 'dark', Record<string, string>> = {
  light: {
    surface: '#F6F8F9', plane: '#EDF1F3', panel: '#FFFFFF', 'ink-1': '#13222E', 'ink-2': '#46596A',
    muted: '#5A6B7E', hairline: '#D5DDE2', ring: '#7D8E9C', context: '#74859A',
    outgoing: '#2A78D6', incoming: '#EB6834', path: '#17A070', issue: '#D03B3B',
  },
  dark: {
    surface: '#0F151A', plane: '#0A0F13', panel: '#141B21', 'ink-1': '#E8EEF2', 'ink-2': '#A9B8C4',
    muted: '#8C9DAB', hairline: '#24303A', ring: '#5E7080', context: '#7F909E',
    outgoing: '#3987E5', incoming: '#D95926', path: '#199E70', issue: '#D03B3B',
  },
};

function luminance(hex: string): number {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contrast(a: string, b: string): number {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

for (const theme of ['light', 'dark'] as const) {
  test(`G15 ${theme} tokens equal the specification`, () => {
    const got = Object.fromEntries(Object.entries(tokens[theme]).map(([k, v]) => [k, String(v).toUpperCase()]));
    expect(got).toEqual(SPEC[theme]);
  });
  test(`G15 ${theme} contrast: text at least 4.5 to 1, graphics at least 3 to 1`, () => {
    const t = SPEC[theme];
    for (const ink of ['ink-1', 'ink-2', 'muted']) {
      for (const ground of ['surface', 'plane', 'panel']) {
        expect(contrast(t[ink], t[ground]), `${ink} on ${ground}`).toBeGreaterThanOrEqual(4.5);
      }
    }
    for (const mark of ['ring', 'context', 'outgoing', 'incoming', 'path', 'issue']) {
      expect(contrast(t[mark], t.surface), `${mark} on surface`).toBeGreaterThanOrEqual(3);
    }
  });
}
